export interface ConversationPage {
  items: ConversationSummary[];
  /** Opaque cursor for the next page; absent on the last page. Send it back as `?cursor=` (GET) or `SearchRequest.cursor`. */
  next?: string;
}

/** A message as GET /api/conversations/{id} returns it. Assistant `steps` are the flat step.* and escalation events in stream order (canonical; rebuild the timeline with the same reducer as the live stream). */
export interface StoredMessage {
  id: ID;
  role: 'user' | 'assistant';
  createdAt: Timestamp;
  parentId?: ID;
  /** User messages. */
  text?: string;
  /** User messages: the message this one edits (a sibling of it). Without parentId it is a root. */
  editOf?: ID;
  /** Assistant messages: the answer this one regenerates. */
  regenerateOf?: ID;
  parts?: Part[];
  steps?: {
    type: string;
  }[];
  finishReason?: 'stop' | 'abstain' | 'needs_input' | 'error' | 'aborted';
  usage?: Usage;
  /** Assistant messages: the user's thumbs up/down (1.7.0). */
  feedback?: Feedback;
  /** Assistant messages: same as message.end.sources (1.8.0). */
  sources?: Source[];
  /** 1.10.0: assistant messages, the style this regeneration used (absent for `default`). */
  regenerateStyle?: RegenerateStyle;
}

/** GET /api/conversations/{id}. */
export interface Conversation {
  id: ID;
  title: string;
  updatedAt: Timestamp;
  messages: StoredMessage[];
  /** 1.17.0: pinned to the top of the sidebar. The plain list returns pinned chats first (most recently pinned on top), then the rest newest first; search stays newest first. Always sent by 1.17+ servers. */
  pinned?: boolean;
  /** 1.17.0: archived chats leave the sidebar but stay searchable and openable. Archiving drops the pin; pinning or sending a new question in an archived chat unarchives it. Always sent by 1.17+ servers. */
  archived?: boolean;
}

/** GET /api/transcripts. */
export interface TranscriptsInfo {
  mode: 'ephemeral' | 'persisted';
  persisted: boolean;
  retentionDays: number | null;
}

/** PATCH /api/conversations/{id}. `title`: one line of text; empty resets to the generic title; 422 invalid_title otherwise. 1.17.0: also `pinned` / `archived`; send at least one field; `pinned: true` with `archived: true` is a 422 validation. Pin/archive do not change `updatedAt`. */
export interface RenameRequest {
  title?: string;
  pinned?: boolean;
  archived?: boolean;
}

/** Body of a successful PATCH /api/conversations/{id} (rename, pin or archive). 1.17.0: carries `pinned` and `archived`. */
export interface RenameResponse {
  id: ID;
  title: string;
  updatedAt: Timestamp;
  /** 1.17.0: pinned to the top of the sidebar. The plain list returns pinned chats first (most recently pinned on top), then the rest newest first; search stays newest first. Always sent by 1.17+ servers. */
  pinned?: boolean;
  /** 1.17.0: archived chats leave the sidebar but stay searchable and openable. Archiving drops the pin; pinning or sending a new question in an archived chat unarchives it. Always sent by 1.17+ servers. */
  archived?: boolean;
}

/** POST /api/conversations/search (POST so search text, possibly PHI, never sits in a URL). */
export interface SearchRequest {
  q?: string;
  cursor?: string;
  /** 1.17.0: default `include` (archived chats stay searchable). */
  archived?: ConversationArchivedFilter;
}

/** Relative cost per answer, for a picker badge. Not a price. */
export type CostTier = 'low' | 'medium' | 'high';

/** One answer strategy a picker can offer. */
export interface StrategyOption {
  /** Send as ChatRequest.options.strategy; echoed on message.start.strategy. */
  id: string;
  label: string;
  description: string;
  default: boolean;
  costTier: CostTier;
  latencyTier?: 'fast' | 'medium' | 'slow';
  /** ModelOption ids allowed with this strategy. */
  models: string[];
  /** False: show it disabled (not enabled for this organization; see unavailableReason). Sending it anyway is a 422 validation. */
  available: boolean;
  /** Why it is unavailable for this organization (show as a tooltip). Present iff available is false. */
  unavailableReason?: string;
}

/** One model a picker can offer. */
export interface ModelOption {
  /** Send as ChatRequest.options.model. 'auto' lets the server choose. */
  id: string;
  label: string;
  description?: string;
  default: boolean;
  tier?: 'small' | 'medium' | 'large';
  provider?: string;
  costTier: CostTier;
  /** False: show it disabled for this organization. */
  available: boolean;
  /** Why it is unavailable for this organization (show as a tooltip). Present iff available is false. */
  unavailableReason?: string;
}

/** GET /api/capabilities: what this server can run. Fetch once per session; no user data. */
export interface Capabilities {
  contractVersion: string;
  /** True with the scripted demo LLM: the choice is validated and echoed but the demo scenario drives the run. */
  demo: boolean;
  defaults: {
    strategy: string;
    model: string;
  };
  strategies: StrategyOption[];
  models: ModelOption[];
  /** 'organization' when the request was signed in, so `available` reflects the caller's organization; 'public' otherwise (everything shows available; the chat request is still checked). This is about which strategies/models are shown as available. It is not a data scope: the data a user can query comes from their sign-in and is never chosen or shown as a choice (§2.1). */
  scope: 'organization' | 'public';
  /** 1.7.0: reason chips for answer feedback, grouped by rating. */
  feedbackReasons?: FeedbackReason[];
  /** 1.14.0: how the server masks literals in shown SQL (CONTRACT.md §10). `phi` (default): literals compared with PHI-bearing columns, and identifier-like values; `all`: every string literal and compared number; `off`: verbatim. Open (render an unknown value as `phi`). Absent from pre-1.14 servers: assume `off`. */
  sqlLiteralMasking?: 'phi' | 'all' | 'off';
  /** 1.15.0: share-link lifetimes for the share dialog (§17). Absent from pre-1.15 servers: links never expire. */
  shareExpiry?: {
    options: ShareExpiryDays[];
    default: ShareExpiryDays;
  };
  /** 1.17.0: true when PATCH /api/conversations/{id} persists `pinned` / `archived` server-side. Absent on older servers: hide Pin/Archive or keep them client-only. */
  pinArchive?: boolean;
  /** 1.20.0: present when the server honours `ChatRequest.temporary` (§11.1). Absent on older servers: offer temporary chat only as a client-side mode, or not at all. */
  temporaryChat?: {
    /** Idle lifetime of the server-side history that lets edit and regenerate work inside the open temporary chat. */
    ttlSeconds: number;
  };
}

/** Wall-clock milliseconds per pipeline stage (1.6.0). Every instant of the run is attributed to exactly one stage, so the stages sum to about latency.totalMs (minus queueMs and time before the analyzer starts). plan: model turns and schema exploration; sql: running queries; repair: from a failed query or failed verification until the repaired query returns (model + SQL); checks: result checks after the final query; render: writing the answer parts. With parallel candidates the attribution follows the latest stage change, so treat it as approximate. 1.14.0: the five stages sum to exactly `totalMs`. */
export interface LatencyStages {
  plan: number;
  sql: number;
  repair: number;
  checks: number;
  render: number;
}

/** Closed. Thumbs up or down. */
export type FeedbackRating = 'up' | 'down';

/** A reason chip for one rating (1.7.0). Listed in Capabilities.feedbackReasons; ids are stable. */
export interface FeedbackReason {
  id: string;
  label: string;
  rating: FeedbackRating;
}

/** PUT /api/conversations/{conversationId}/messages/{messageId}/feedback (1.7.0). Assistant messages only. Replaces earlier feedback; DELETE on the same path clears it ({cleared: true}). 422 validation for an unknown reason, a reason of the other rating, or a user message; 404 for an unknown or someone else's message. */
export interface FeedbackRequest {
  rating: FeedbackRating;
  /** FeedbackReason ids matching the rating. */
  reasons?: string[];
  /** Optional free text. Treated like message text: stored with the transcript, never logged. */
  comment?: string;
}

/** Stored feedback on an answer: the PUT response (with messageId) and StoredMessage.feedback. */
export interface Feedback {
  messageId?: ID;
  rating: FeedbackRating;
  reasons: string[];
  comment?: string;
  updatedAt: Timestamp;
}

/** A data source the answer used or explored (1.8.0, CONTRACT.md §14). Schema identifiers only, never row values. */
export interface Source {
  /** Stable within the message: src_1, src_2, … */
  id: string;
  /** Open enum: 'view' today; 'definition' (metric definition) and 'document' are reserved. Unknown kinds render as a plain chip. */
  kind: 'view' | 'definition' | 'document' | (string & {});
  /** Fully qualified, e.g. sem.claims. */
  name: string;
  label: string;
  description?: string;
  /** 'answer': the final SQL/table read it; 'explored': looked at while planning only. */
  role: 'answer' | 'explored';
  /** step.* events that touched it (sql_running, explore). */
  stepIds?: ID[];
  /** Parts built from it (code, table, chart). */
  partIds?: ID[];
}

/** GET /api/conversations/{id}/export?format=json (1.8.0, §15). format=markdown returns text/markdown instead. Both are attachments (Content-Disposition), Cache-Control: no-store. */
export interface ConversationExport {
  format: 'cc.conversation';
  contractVersion: string;
  exportedAt: Timestamp;
  conversation: Conversation;
}

/** 1.9.0 (§5.1): a table is about to stream. Render the header now, append table.rows, then replace it with the complete `part` that has the same id (that part is canonical). If message.end comes first (aborted), drop the partial table. */
export interface TableStart {
  type: 'table.start';
  partId: ID;
  columns: Column[];
  title?: string;
  sensitivity?: Sensitivity;
  stepId?: ID;
  sqlPartId?: ID;
  seq: number;
}

/** 1.9.0: preview rows for a streaming table, in order. `offset` is the index of the first row, so a replayed chunk (Last-Event-ID) overwrites rather than duplicates. */
export interface TableRows {
  type: 'table.rows';
  partId: ID;
  offset: number;
  rows: unknown[][];
  seq: number;
}

/** 1.18.0 (§5.2): a chart is about to stream. The header has every field needed for the first draw; draw from the first `chart.points`. The complete `part` with the same id follows and is canonical. If message.end comes first (aborted/error), drop the partial chart. */
export interface ChartStart {
  type: 'chart.start';
  partId: ID;
  plot: PlotHeader;
  alt?: string;
  tablePartId?: ID;
  sensitivity?: Sensitivity;
  seq: number;
}

/** 1.18.0: points for a streaming chart, in order. `offset` is the index of the first point, so a replayed chunk overwrites rather than duplicates. */
export interface ChartPoints {
  type: 'chart.points';
  partId: ID;
  offset: number;
  rows: PlotRow[];
  seq: number;
}

/** 1.10.0: how a regenerated answer is restyled (CONTRACT.md §8.1). `default` means a plain re-run. `concise` cuts the prose to its first sentence and drops a chart that duplicates a table. `detailed` adds a 'How this was computed' paragraph. Tables, SQL, artifacts and every assumption/caveat callout are always kept. */
export type RegenerateStyle = 'default' | 'concise' | 'detailed';

/** 1.11.0: PUT /api/conversations/{id}/share body (CONTRACT.md §17). 1.15.0: `expiresInDays`; turning `includeData` on issues a new share id. */
export interface ShareRequest {
  /** Share the stored preview rows (≤ 50 per table, never the CSV). Default false: tables are shown without rows, and charts and data artifacts are left out. 1.15.0: turning it on (false→true) issues a NEW share id and revokes the old one (S1); turning it off keeps the id. */
  includeData?: boolean;
  /** 1.15.0: 7, 30 or 90 days from this request. Omitted: keep the current expiry (a new or rotated share gets 30). */
  expiresInDays?: ShareExpiryDays;
}

/** 1.11.0: the active share of a conversation. Read-only, org-scoped and revocable. 1.15.0: expires (`expiresAt`), and widening data issues a new id (`rotated`). */
export interface ShareLink {
  shareId: ID;
  conversationId: ID;
  /** App-relative path. The viewer must be signed in to the same organization. */
  url: string;
  scope: 'organization';
  includeData: boolean;
  createdAt: Timestamp;
  /** 1.15.0: when the link stops working (the viewer then gets 404, like a revoked link). Show it in the share dialog. Absent from pre-1.15 servers: no expiry. */
  expiresAt?: Timestamp;
  /** 1.15.0: the lifetime chosen (7, 30 or 90 today), to preselect the dialog's choice. */
  expiresInDays?: number;
  /** 1.15.0: true when this PUT widened `includeData` and so replaced the share id; the old link is revoked. Tell the owner to send the new link. */
  rotated?: boolean;
}

/** 1.11.0: GET /api/shared/{shareId}. The owner's conversation, read-only. Feedback, file ids and (unless includeData) rows are removed. 1.15.0: with `includeData: false`, SQL is withheld too (`sqlWithheld`). */
export interface SharedConversation {
  shareId: ID;
  title?: string | null;
  /** Null when the conversation has not changed since it was shared. */
  updatedAt?: Timestamp | null;
  includeData: boolean;
  createdAt: Timestamp;
  messages: StoredMessage[];
  /** 1.15.0: when this link expires. */
  expiresAt?: Timestamp;
  /** 1.15.0 (QA-S18): true when `includeData` is false. SQL `code` parts are removed, `table.sqlPartId` is dropped, and SQL in steps (`sql`, `revisedSql`, `candidates[].sql`) and in `tool_call.input.sql` is the empty string. Say "SQL not shared" instead of an empty code block. */
  sqlWithheld?: boolean;
}

/** 1.13.0: `HttpError.error.code`. Open: branch on the known values, and on the HTTP status for anything else. A server may send `http_<status>` for a status with no dedicated code. When a code gets more specific the old one stays in `legacyCode` for at least one minor version. */
export type ErrorCode = 'auth_expired' | 'access_denied' | 'not_found' | 'method_not_allowed' | 'stream_gone' | 'validation' | 'invalid_title' | 'clarification_expired' | 'transcripts_unavailable' | 'payload_too_large' | 'rate_limited' | 'internal' | (string & {});

/** 1.15.0 (S4): how long a share link lives, in days. 30 is the default. Closed: the server rejects other values with 422. */
export type ShareExpiryDays = 7 | 30 | 90;

/** 1.17.0: `GET /api/conversations?archived=` and `SearchRequest.archived`. `include` (default) lists everything, `exclude` is the sidebar, `only` is Settings → Archived chats. */
export type ConversationArchivedFilter = 'include' | 'exclude' | 'only';

/** 1.21.0 (BACKEND-FIT): names a client can never send in `ChatRequest` or `ChatRequest.options`, because the customer, the data source and the queryable relations come only from the signed-in identity, server-side (production: the Cognito id token's `custom:customer` claim, then `ccsim.query.open_session` with that customer's manifest; demo: the demo token and `DEMO_DIRECTORY`). Sending one is 422 `validation`; nothing is run. CONTRACT.md §2.1. */
export type IdentityScopedKey = 'catalog' | 'connection' | 'customer' | 'customerId' | 'database' | 'dataSource' | 'db' | 'escalate' | 'lake' | 'org' | 'orgId' | 'organization' | 'relations' | 'schema' | 'scope' | 'source' | 'tables' | 'tenant' | 'tenantId' | 'warehouse';

export const KNOWN_PART_TYPES = ['text', 'reasoning', 'status', 'tool_call', 'table', 'file', 'image', 'chart', 'code', 'callout', 'artifact', 'error', 'abstain', 'clarification'] as const;
export const KNOWN_EVENT_TYPES = ['message.start', 'status', 'step.sql_running', 'step.sql_result', 'step.repair_attempt', 'step.check', 'step.explore', 'step.candidates', 'escalation', 'text.start', 'text.delta', 'text.end', 'reasoning.delta', 'reasoning.end', 'code.delta', 'table.start', 'table.rows', 'chart.start', 'chart.points', 'part', 'part.patch', 'message.end', 'heartbeat'] as const;
/** 1.12.0: required fields of each event and their JSON kinds, for `wellFormed()` (fail-safe reducer input). */
export const EVENT_SHAPES: Record<string, Record<string, readonly string[]>> = {"message.start": {"messageId": ["string"], "conversationId": ["string"], "contractVersion": ["string"]}, "status": {"label": ["null", "string"]}, "step.sql_running": {"stepId": ["string"], "sql": ["string"], "purpose": ["string"], "attempt": ["integer"]}, "step.sql_result": {"stepId": ["string"], "ok": ["boolean"], "elapsedMs": ["integer"]}, "step.repair_attempt": {"stepId": ["string"], "failedStepId": ["string"], "attempt": ["integer"], "error": ["object"], "revisedSql": ["string"]}, "step.check": {"stepId": ["string"], "check": ["string"], "verdict": ["string"], "message": ["string"]}, "step.explore": {"stepId": ["string"], "probe": ["string"], "summary": ["string"]}, "step.candidates": {"stepId": ["string"], "candidates": ["array"], "chosenId": ["null", "string"], "method": ["string"]}, "escalation": {"from": ["object"], "to": ["object"], "reason": ["string"], "trigger": ["string"]}, "text.start": {"partId": ["string"]}, "text.delta": {"partId": ["string"], "delta": ["string"]}, "text.end": {"partId": ["string"]}, "reasoning.delta": {"partId": ["string"], "delta": ["string"]}, "reasoning.end": {"partId": ["string"], "durationMs": ["integer"]}, "code.delta": {"partId": ["string"], "delta": ["string"]}, "table.start": {"partId": ["string"], "columns": ["array"]}, "table.rows": {"partId": ["string"], "offset": ["integer"], "rows": ["array"]}, "chart.start": {"partId": ["string"], "plot": ["object"]}, "chart.points": {"partId": ["string"], "offset": ["integer"], "rows": ["array"]}, "part": {"part": ["object"]}, "part.patch": {"partId": ["string"], "patch": ["object"]}, "message.end": {"messageId": ["string"], "finishReason": ["string"], "usage": ["object"]}, "heartbeat": {}};
/** 1.13.0: enums a newer server may extend (CONTRACT.md §3). Render an unknown value as `fallback`. */
export const OPEN_ENUM_FALLBACKS: Record<string, string> = {"ColumnType": "string", "ModelRef.tier": "medium", "CodePart.role": "snippet", "CalloutPart.variant": "info", "ArtifactPart.kind": "report", "AbstainPart.category": "unsupported", "StepSqlRunning.purpose": "answer", "StepCheck.action": "none", "Escalation.trigger": "complexity", "Capabilities.sqlLiteralMasking": "phi"};
/** 1.13.0: open string fields and the values known in this version. Anything else is valid. */
export const OPEN_KNOWN_VALUES: Record<string, readonly string[]> = {"StepError.code": ["binder_error", "syntax_error", "timeout", "guard_blocked", "query_failed", "cancelled"], "Usage.models.role": ["analyst", "escalation", "judge", "verifier"], "ErrorPart.code": ["internal", "query_failed", "access_denied", "timeout", "rate_limited", "auth_expired", "validation", "offline"], "StepCheck.check": ["verifier", "row_count", "null_share", "join_fanout", "date_range", "definition"], "StepExplore.probe": ["list_views", "describe_view", "sample_values", "lookup_glossary", "lookup_dictionary", "search_examples", "profile", "request_escalation"], "StepCandidates.method": ["vote", "execution_agreement", "verifier", "judge"], "Source.kind": ["view", "definition", "document"], "ErrorCode": ["auth_expired", "access_denied", "not_found", "method_not_allowed", "stream_gone", "validation", "invalid_title", "clarification_expired", "transcripts_unavailable", "payload_too_large", "rate_limited", "internal"]};
/** 1.18.0: PlotSpec enums and caps, for the zod mirror in web/src/contract/plot.ts (one source). */
export const PLOT_SCHEMA = {"version": 1, "kinds": ["bar", "line", "area", "point"], "fieldTypes": ["temporal", "nominal", "ordinal", "quantitative"], "formats": ["currency", "percent", "integer", "number", "date", "month"], "sorts": ["-y", "x", "none"], "temporalPattern": "^[0-9]{4}-[0-9]{2}(-[0-9]{2}([T ][0-9]{2}:[0-9]{2}(:[0-9]{2}(\\.[0-9]{1,9})?)?(Z|[+-][0-9]{2}:?[0-9]{2})?)?)?(?![\\s\\S])", "fieldPattern": "^[A-Za-z_][A-Za-z0-9_]{0,63}(?![\\s\\S])", "caps": {"maxPoints": 2000, "minPoints": 1, "maxSeries": 10, "maxTitle": 120, "maxAxisTitle": 80, "maxString": 200, "maxFieldName": 64, "chunkPoints": 50}} as const;
export type PartType = Part['type'];
export type StreamEventType = StreamEvent['type'];
